mapper.select:
SELECT * FROM plt_delivery_material WHERE tenant_id = #{query.tenantId} AND id IN
#{id}
AND deleted = b'0' ORDER BY id FOR UPDATE

SELECT * FROM plt_delivery_material
WHERE tenant_id=#{query.tenantId} AND deleted=b'0'
  AND ((owner_module=#{query.ownerModule} AND entity_id=#{query.entityId}
        AND (entity_type=#{query.entityType}
            OR entity_type='REQUIREMENT_ANALYSIS'))
    OR (source_owner_module=#{query.ownerModule} AND source_entity_id=#{query.entityId}
        AND (source_entity_type=#{query.entityType}
            OR source_entity_type='REQUIREMENT_ANALYSIS')))

  AND (type_code=#{query.typeCode} OR business_type_code=#{query.typeCode})

ORDER BY id DESC

mapper.sql:
m.tenant_id=#{query.tenantId} AND m.project_id=#{query.projectId} AND m.deleted=b'0'
  AND m.material_kind='FILE' AND m.status='ACTIVE' AND m.source_kind IN ('UPLOAD','ASSOCIATED')
  AND EXISTS (SELECT 1 FROM plt_file_reference r WHERE r.tenant_id=#{query.tenantId}
    AND r.id=m.file_reference_id AND r.owner_context='PLT' AND r.object_type='DEFAULT_BUSINESS_DELIVERY')

    AND CAST(m.business_type_code AS BINARY) IN #{type}
  AND 1=0
  AND CAST(m.type_code AS BINARY)=CAST(#{query.deliverableType} AS BINARY)
  AND CAST(m.business_type_code AS BINARY)=CAST(#{query.businessType} AS BINARY)
  AND m.entity_id=#{query.entityId}

mapper.select:
SELECT * FROM plt_delivery_material WHERE tenant_id=#{query.tenantId}
  AND source_identity_key=#{query.sourceIdentityKey} AND source_kind IN ('UPLOAD','ASSOCIATED')
  AND EXISTS (SELECT 1 FROM plt_file_reference r WHERE r.tenant_id=#{query.tenantId}
    AND r.id=plt_delivery_material.file_reference_id AND r.object_type='DEFAULT_BUSINESS_DELIVERY' AND r.owner_context='PLT') FOR UPDATE
